// BannerCopyGenerator2.tsx (타입스크립트 + 지그재그톤 확장 + 필터링)
import React, { useState, useRef, DragEvent, ChangeEvent } from "react";
import ColorThief from "color-thief-browser";

interface BannerCopyGeneratorProps {
  onHome: () => void;
  onBack?: () => void;
  onNavigate?: (guide: string) => void;
}

interface MoodItem {
  color: string;
  mood: string;
}

interface SelectedTags {
  style: string[];
  fit: string[];
  mood: string[];
  season: string[];
  situation: string[];
  colorTone: string[];
  noun: string[];
}

// 소비자 친화 무드
const moods: string[] = [
  '고요한', '무심한', '따뜻한', '말랑한', '깔끔한', '세련된', '청순한', '활기찬',
  '도시적인', '툭 던진', '낙낙한', '햇살 같은', '부드럽게 흐르는', '쨍한', '투명한', '가벼운',
  '여유로운', '살짝 힘 뺀', '말 안 해도 아는', '잔잔한', '감도 높은', '잔향 같은'
];

// 상황 키워드 (하객룩 제외, 파티는 유지하되 낮은 확률로 제어 가능)
const situations: string[] = [
  '출근', '데일리', '여행', '데이트', '주말', '소풍', '약속', '휴가', '홈웨어',
  '기분전환', '가볍게 나가는 날', '뭐 입지 고민될 때', '편하게 멋내고 싶은 날'
];

const nouns: string[] = [
  '실루엣', '컬러감', '포인트', '디테일', '라인', '핏', '무드', '스타일', '여운', '결', '톤', '감촉',
  '포인트감', '바람결', '느낌', '취향', '무늬', '소재', '스며듦', '빛감'
];

const adjToAdv: Record<string, string> = {
  "툭 던진": "툭 던지듯",
  "햇살 같은": "햇살처럼",
  "말 안 해도 아는": "말 안 해도 아는 느낌으로",
  "낙낙한": "낙낙하게",
  "살짝 힘 뺀": "살짝 힘 빼고",
  "감도 높은": "감도 높게",
  "부드럽게 흐르는": "부드럽게",
  "여유로운": "여유롭게",
  "잔향 같은": "잔향처럼"
};

// 문장 자연화 보정 로직 (기호 제거 및 특수 상황 제거)
const sanitizePhrase = (phrase: string): string => {
  return phrase
    .replace(/[.,;:!?]/g, '')              // 특수기호 제거
    .replace(/\s{2,}/g, ' ')               // 중복 공백 제거
    .replace(/하객룩/g, '')                // 불필요한 상황 제거
    .replace(/\s+/g, ' ')                  // 전체 공백 정리
    .trim();
};

